 check("due_soon_uses_explicit_due_date",num(((Map<?,?>)s.list(actor,all).get("counts")).get("dueSoon"))==1);s.act(actor,f.record,"occupational",req(s,actor,f.record,"occupational","submit"));check("submit_is_persisted_stage","pending_employee".equals(s.detail(actor,f.record,"occupational",null).get("status")));Map<String,Object> confirm=req(s,actor,f.record,"occupational","confirm");confirm.put("evidenceVerified",true);confirm.put("sourceId",f.source);s.act(actor,f.record,"occupational",confirm);Map<String,Object> review=req(s,actor,f.record,"occupational","review");review.put("identityVerified",true);review.put("contentVerified",true);s.act(actor,f.record,"occupational",review);Map<String,Object> archive=req(s,actor,f.record,"occupational","archive");reject("archive_requires_explicit_verification",422,()->s.act(actor,f.record,"occupational",archive));archive.put("archiveVerified",true);ehr.candidateOnly=true;reject("candidate_archive_denied",403,()->s.act(actor,f.record,"occupational",archive));ehr.candidateOnly=false;s.act(actor,f.record,"occupational",archive);check("archive_completes_document_stream","archived".equals(s.detail(actor,f.record,"occupational",null).get("status")));check("completion_counts_real_status",num(((Map<?,?>)s.list(actor,all).get("counts")).get("completed"))==1);check("source_report_not_published_by_form_archive",db.count("SELECT COUNT(*) FROM a_report_publications WHERE report_id=?",f.report)==0);
